BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA identity; CREATE SCHEMA core; CREATE SCHEMA authz; CREATE SCHEMA recruiting; CREATE SCHEMA audit;
CREATE TYPE core.application_status AS ENUM ('submitted','in_review','needs_info','rejected','approved');
CREATE TYPE core.organization_status AS ENUM ('active','suspended');
CREATE TYPE core.membership_status AS ENUM ('invited','active','suspended');
CREATE TABLE identity.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity.external_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES identity.users(id), issuer text NOT NULL, subject text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE identity.platform_admins(user_id uuid PRIMARY KEY REFERENCES identity.users(id), granted_by uuid REFERENCES identity.users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.organization_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_user_id uuid NOT NULL REFERENCES identity.users(id), requested_name text NOT NULL, requested_slug text NOT NULL, purpose text NOT NULL, status core.application_status NOT NULL DEFAULT 'submitted', reviewer_user_id uuid REFERENCES identity.users(id), review_note text, reviewed_at timestamptz, organization_id uuid UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, CHECK(length(trim(requested_name)) BETWEEN 2 AND 150), CHECK(requested_slug ~ '^[a-z0-9][a-z0-9-]{2,62}$'));
CREATE TABLE core.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, status core.organization_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE core.organization_applications ADD CONSTRAINT application_org_fk FOREIGN KEY(organization_id) REFERENCES core.organizations(id);
CREATE UNIQUE INDEX application_live_slug ON core.organization_applications(requested_slug) WHERE status IN ('submitted','in_review','needs_info');
CREATE TABLE core.memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), user_id uuid NOT NULL REFERENCES identity.users(id), status core.membership_status NOT NULL DEFAULT 'invited', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id), UNIQUE(id,organization_id));
CREATE TABLE authz.permissions(key text PRIMARY KEY, description text NOT NULL);
CREATE TABLE authz.roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), key text NOT NULL, name text NOT NULL, system_role boolean NOT NULL DEFAULT false, UNIQUE(organization_id,key), UNIQUE(id,organization_id));
CREATE TABLE authz.role_grants(role_id uuid NOT NULL REFERENCES authz.roles(id) ON DELETE CASCADE, permission_key text NOT NULL REFERENCES authz.permissions(key), scope text NOT NULL CHECK(scope IN ('own','team','organization')), PRIMARY KEY(role_id,permission_key));
CREATE TABLE authz.membership_roles(organization_id uuid NOT NULL, membership_id uuid NOT NULL, role_id uuid NOT NULL, PRIMARY KEY(membership_id,role_id), FOREIGN KEY(membership_id,organization_id) REFERENCES core.memberships(id,organization_id) ON DELETE CASCADE, FOREIGN KEY(role_id,organization_id) REFERENCES authz.roles(id,organization_id) ON DELETE CASCADE);
CREATE TABLE core.teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), name text NOT NULL, UNIQUE(id,organization_id));
CREATE TABLE core.team_memberships(organization_id uuid NOT NULL, team_id uuid NOT NULL, membership_id uuid NOT NULL, team_role text NOT NULL DEFAULT 'member' CHECK(team_role IN ('member','lead')), PRIMARY KEY(team_id,membership_id), FOREIGN KEY(team_id,organization_id) REFERENCES core.teams(id,organization_id), FOREIGN KEY(membership_id,organization_id) REFERENCES core.memberships(id,organization_id));
CREATE TABLE core.modules(key text PRIMARY KEY, name text NOT NULL);
CREATE TABLE core.organization_modules(organization_id uuid NOT NULL REFERENCES core.organizations(id), module_key text NOT NULL REFERENCES core.modules(key), enabled boolean NOT NULL DEFAULT false, config jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(organization_id,module_key));
CREATE TABLE recruiting.contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), display_name text NOT NULL, email text, phone text, lawful_basis text, contact_permission jsonb NOT NULL DEFAULT '{}'::jsonb, retention_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(id,organization_id));
CREATE TABLE recruiting.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), contact_id uuid NOT NULL, assigned_membership_id uuid, assigned_team_id uuid, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','appointment','won','lost')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id), FOREIGN KEY(contact_id,organization_id) REFERENCES recruiting.contacts(id,organization_id), FOREIGN KEY(assigned_membership_id,organization_id) REFERENCES core.memberships(id,organization_id), FOREIGN KEY(assigned_team_id,organization_id) REFERENCES core.teams(id,organization_id));
CREATE INDEX leads_org_status ON recruiting.leads(organization_id,status); CREATE INDEX leads_org_assignee ON recruiting.leads(organization_id,assigned_membership_id);
CREATE TABLE audit.events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid REFERENCES core.organizations(id), actor_user_id uuid REFERENCES identity.users(id), action text NOT NULL, target_type text NOT NULL, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_org_created ON audit.events(organization_id,created_at DESC);
-- RLS tenant context is set ONLY by a trusted server-side transaction using SET LOCAL.
CREATE FUNCTION core.current_org() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('fieldhub.organization_id',true),'')::uuid $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['core.teams','core.team_memberships','core.memberships','core.organization_modules','authz.roles','authz.membership_roles','recruiting.contacts','recruiting.leads','audit.events'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %s USING (organization_id = core.current_org()) WITH CHECK (organization_id = core.current_org())',t); END LOOP; END $$;
-- Ownership, role grants, applications and identities are accessed through separately privileged services;
-- never grant the runtime role unrestricted access to these tables.
COMMIT;
